update public.manufacturers set warranty_summary = 'One year from purchase, one-time repair or replacement. The original receipt is required.', warranty_source = 'Research summary, 1 November 2026 (docs/NEW-BAT-RESEARCH.md). Check the manufacturer''s current terms.' where slug = 'miken';
update public.manufacturers set warranty_summary = 'One year from purchase, one-time repair or replacement. The original receipt is required.', warranty_source = 'Research summary, 1 November 2026 (docs/NEW-BAT-RESEARCH.md). Check the manufacturer''s current terms.' where slug = 'worth';
